diagrams=[]
def diagram(id,title,kind,keys=None,notes='',**kw):
 d=dict(id=id,title=title,kind=kind,notes=notes,**kw)
 if keys is not None:d['keys']=keys
 diagrams.append(d);return d
def seq(id,title,nodes,steps,notes=''):
 return diagram(id,title,'sequence',nodes=[dict(key=k,title=v,kind='Actor' if k=='actor' else 'Object',classifier=v if v in by else None) for k,v in nodes],steps=[dict(note=s[0]) if len(s)==1 else dict(a=s[0],b=s[1],text=s[2],reply=(len(s)>3 and s[3])) for s in steps],notes=notes or 'Recorrido principal implementado; las excepciones y condiciones se indican mediante notas. No incorpora funciones propuestas.')
def uc(id,title,actor,actions,notes=''):
 nodes=[dict(key='actor',title=actor,kind='Actor')]+[dict(key='u'+str(i),title=s,kind='UseCase') for i,s in enumerate(actions)]
 return diagram(id,title,'usecase',nodes=nodes,edges=[dict(a='actor',b='u'+str(i),kind='Association',label='') for i in range(len(actions))],notes=notes)
refs=[]
for p in sorted(R.glob('SIGAT.*/*.csproj')):
 layer=p.parent.name
 if layer=='SIGAT.Tests':continue
 for e in ET.parse(p).getroot().iter('ProjectReference'):refs.append(dict(a=layer,b=Path(e.attrib['Include'].replace('\\','/')).stem,kind='Dependency',label='use'))
