for i,layer in enumerate(['SIGAT.BE','SIGAT.BLL','SIGAT.DAL','SIGAT.SERVICIOS','SIGAT.UI'],2):
 keys=[t['name'] for t in types if t['layer']==layer]
 diagram(f'{i:02}_clases_{layer.split(".")[-1].lower()}',f'G06 Clases de {layer}','class',keys,notes='Vista integrada de todos los tipos de esta capa. Se muestran miembros principales; las firmas completas y archivos fuente constan en las notas de cada elemento. Los controles generados del Designer se omiten. Separación: entidades y contratos del dominio administrativo en BE; infraestructura e implementación técnica en las otras capas.',group='G06 Clases por capa')
old=json.loads((R/'entregables/modelo_actualizado_20261012/fuentes/esquema_sql.json').read_text(encoding='utf-8-sig'))
sql=(R/'Querys/01_Instalacion_Completa.sql').read_text(encoding='utf-8-sig')
# The existing physical schema is checked against the installer; new ALTER columns are applied explicitly.
schema={'columns':old['columns'],'foreignKeys':old['foreignKeys'],'uniqueKeys':old['uniqueKeys'],'source':'Querys/01_Instalacion_Completa.sql','sha256':hashlib.sha256((R/'Querys/01_Instalacion_Completa.sql').read_bytes()).hexdigest()}
for table in ['Usuarios','UsuarioRol']:
 if not any(c['Tabla']==table and c['Columna']=='DigitoVerificador' for c in schema['columns']):schema['columns'].append(dict(Tabla=table,Columna='DigitoVerificador',Tipo='char',Longitud=64,Nulo=True,Identidad=False,PK=0))
tables=sorted({c['Tabla'] for c in schema['columns']})
assert len(tables)==15
for table in tables:
 assert re.search(r'CREATE\s+TABLE\s+(?:\[?dbo\]?\.)?\[?'+re.escape(table)+r'\]?\s*\(',sql,re.I),table
for c in schema['columns']:
 assert re.search(r'\b'+re.escape(c['Columna'])+r'\b',sql),c
(F/'esquema_sql_actual.json').write_text(json.dumps(schema,ensure_ascii=False,indent=2),encoding='utf-8-sig')
