# Derive associations and dependencies from source, preserving inheritance and realization.
edges=[];seen=set()
for t in types:
 for base in t['bases']:
  target=base.split('<')[0].rstrip('?')
  if target in by:edges.append(dict(a=t['name'],b=target,kind='Realisation' if by[target]['kind']=='Interface' else 'Generalization',label=''))
 for f in t['fields']:
  if f.get('generated'):continue
  for target in by:
   if target==t['name'] or '.' in target:continue
   if re.search(r'(?<![\w.])'+re.escape(target)+r'(?!\w)',f['type']):
    key=(t['name'],target)
    if key not in seen:edges.append(dict(a=t['name'],b=target,kind='Association',label=f['name'],many=('List<' in f['type'] or 'Dictionary<' in f['type'])));seen.add(key)
 for target in t['uses']:
  if target in by and target!=t['name'] and (t['name'],target) not in seen and target not in t['bases']:
   edges.append(dict(a=t['name'],b=target,kind='Dependency',label='use'));seen.add((t['name'],target))
# Do not infer relationships of the containing class from nested implementation records.
for t in types:
 t['displayFields']=[f for f in t['fields'] if not f.get('generated') and (f['scope']!='Private' or f['type'] in by or 'List<' in f['type'])][:8]
 if any(f['name']=='DigitoVerificador' for f in t['fields']) and not any(f['name']=='DigitoVerificador' for f in t['displayFields']):t['displayFields']=t['displayFields'][:7]+[f for f in t['fields'] if f['name']=='DigitoVerificador']
 public=[m for m in t['methods'] if m['scope'] in ('Public','Protected') and m['name'] not in ['Dispose','InitializeComponent']]
 important=[m for m in t['methods'] if m['scope']=='Private' and (m['name'].endswith('_Click') or m['name'] in ['Examinar','Bloquear','RestaurarFila','RestaurarSeguridadCompleta','NotificarObservadores','RefrescarArboles','Ejecutar','Main'])]
 t['displayMethods']=(public+important)[:9]
# Supplemental relation evidence used in notes and validation; all class references resolve to current source types.
model=dict(date='2026-10-21',classes=types,edges=edges,diagrams=diagrams,schema=schema,sources=data['sources'])
(F/'modelo.json').write_text(json.dumps(model,ensure_ascii=False,indent=2),encoding='utf-8-sig')
print(f'{len(types)} tipos reales; {len(tables)} tablas de instalación; {len(diagrams)} diagramas; {len(edges)} relaciones de código.')
